const SUPABASE_URL = 'https://vblfdikfobsirwpdnybw.supabase.co';
const SUPABASE_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InZibGZkaWtmb2JzaXJ3cGRueWJ3Iiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzMzNzAwODIsImV4cCI6MjA4ODk0NjA4Mn0.GOx3HoMh3P2Zzxz8BxNsfQBfXwsNZNQsdVc3nJaqRy4';
const EVOLUTION_URL = 'http://rk-evolution:8080/message/sendText/construdata-felipe';
const EVOLUTION_API_KEY = 'construdata2026';

const items = $input.all();
const results = [];

for (const item of items) {
    try {
        const raw = item.json.body || item.json;

        // Ignorar eventos de status da mensagem
        if (raw.event && (raw.event === 'messages.update' || raw.event === 'messages.delete' || raw.event === 'send.message')) {
            continue;
        }

        const msg = raw.data || raw;
        const remoteJid = msg.key?.remoteJid || msg.remoteJid;

        // Ignorar grupos ou sem remetente
        if (!remoteJid || remoteJid.includes('@g.us')) continue;

        let phone = remoteJid.replace('@s.whatsapp.net', '').split('@')[0];
        const fromMe = msg.key?.fromMe || false;

        let text = '';
        if (msg.message?.conversation) text = msg.message.conversation;
        else if (msg.message?.extendedTextMessage?.text) text = msg.message.extendedTextMessage.text;
        else if (msg.message?.imageMessage?.caption) text = msg.message.imageMessage.caption;

        // Prevenir Loop do próprio bot
        if (fromMe && text.includes('Construdata - powered by')) continue;
        if (!text && !msg.message?.imageMessage) continue;

        // Função auxiliar para requests síncronos simulados via promises no n8n
        const fetchApi = async (url, options) => {
             const axios = require('axios');
             try {
                 const res = await axios(url, options);
                 return res.data;
             } catch (err) {
                 console.error('Fetch error:', err.message);
                 return null;
             }
        };

        // 1. Lookup Contato Supabase
        // Formatar telefone pra busca (DDI + DDD + 9? + NUM)
        let altPhone = phone;
        if (phone.length === 12 && phone.startsWith('55')) {
             altPhone = phone.slice(0,4) + '9' + phone.slice(4);
        }

        const contatoUrl = `${SUPABASE_URL}/rest/v1/contatos?select=*&or=(telefone_whatsapp.eq.${phone},telefone_whatsapp.eq.${altPhone})`;
        const contatoData = await fetchApi(contatoUrl, {
            method: 'GET',
            headers: {
                'apikey': SUPABASE_KEY,
                'Authorization': `Bearer ${SUPABASE_KEY}`
            }
        });

        if (!contatoData || contatoData.length === 0) {
            // Usuário não cadastrado - IGNORAR SILENCIOSAMENTE PARA NÃO SPAMAR DESCONHECIDOS
            continue;
        }
        const user = contatoData[0];

        // 2. Roteamento Lógico e Preparação da Resposta
        const tl = text.toLowerCase().trim();
        let replyText = '';

        if (tl === 'ajuda' || tl === 'menu' || tl === 'help') {
            replyText = `🤖 *ConstruDataMax Gestão 360*\nOlá ${user.nome}!\n\n📊 *Opções de Comando:*\n1️⃣ Status RDO Hoje\n2️⃣ Equipe e Contatos\n3️⃣ Projetos Ativos\n4️⃣ Dashboard Consolidado\n5️⃣ Reenviar Cobrança (Alerta)\n6️⃣ Falar com IA\n7️⃣ Cobrar RDO\n8️⃣ Meu RDO Diretor\n9️⃣ Lembrar Tarefas\n🔟 Criar Tarefas\n1️⃣1️⃣ Plano de Custos\n1️⃣2️⃣ Tarefas Consórcio\n1️⃣3️⃣ Enviar Tarefa p/ Pessoa\n1️⃣4️⃣ Enviar Tarefa à Diretoria\n1️⃣5️⃣ Enviar Tarefa aos Engs\n1️⃣6️⃣ Enviar Tarefa por Setor\n\n💡 *Atalhos:*\n@tarefa | PROJETO | DESCRIÇÃO\n@rdo | PROJETO | ATIVIDADE\n@pagamento | PROJETO | DESC\n\n🔗 https://construdatamaxv2-clean.vercel.app\n\n_Construdata - powered by FCN_`;
        } 
        else if (['1','2','3','4','5','7','8'].includes(tl) || tl.startsWith('@rdo') || tl.includes('#rdo')) {
            replyText = `🏗️ *Módulo RDO - ${user.nome}*\nEnvie seu Diário de Obra neste formato:\n\n*@rdo* | PROJETO | FRENTE | ATIVIDADE | QUANTIDADE | EQUIPE\n\n_Ex: @rdo | Pardinho | Terraplenagem | Escavação | 100m3 | 3 pessoas_\n\n⏳ (Em breve processamento automático de fotos)`;
        }
        else if (tl === '6' || tl.includes('#ia') || tl.includes('#ai') || tl.startsWith('@ia')) {
            replyText = `🧠 *Módulo de IA Ativado*\nOlá ${user.nome}, eu sou o assistente virtual da Engenharia RK. O que você precisa analisar ou consultar hoje na base de dados das obras?`;
        }
        else if (tl === '11' || tl.startsWith('@pagamento') || tl.includes('#financeiro') || msg.message?.imageMessage) {
            replyText = `💰 *Módulo Financeiro - ${user.nome}*\nRecebi sua solicitação financeira.\n\nSe enviou um comprovante, por favor responda marcando a imagem com:\n*@pagamento* | OBRA | CATEGORIA | DESCRIÇÃO\n\nCategorias: MAT, MDO, DSL, LOC, REF, FRE.`;
        }
        else if (['9','10','12','13','14','15','16'].includes(tl) || tl.startsWith('@tarefa') || tl.includes('#tarefa')) {
            replyText = `📋 *Módulo de Tarefas - ${user.nome}*\nPara registrar uma tarefa no sistema, digite:\n\n*@tarefa* | PROJETO | RESPONSÁVEL | DESCRIÇÃO | PRAZO\n\n_Ex: @tarefa | Osasco | João | Conferir projeto drenagem | 25/04_`;
        }
        else {
            // Fallback Inteligente baseado no Perfil / Cargo do usuário
            const cargo = (user.cargo || '').toLowerCase();

            if (cargo.includes('diretor') || cargo.includes('master')) {
                // Master/Diretores às vezes estão só batendo papo. Retorna menu curto.
                replyText = `Olá Diretor ${user.nome}. Sou o bot do ConstruDataMax. Para comandos, digite *menu*.`;
            } else if (cargo.includes('eng') || cargo.includes('coord')) {
                replyText = `Fala Engenheiro ${user.nome}! Precisando lançar RDO, Tarefa ou Pagamento? Digite *menu* para ver as opções.`;
            } else {
                replyText = `Olá ${user.nome}! Sistema ConstruDataMax ativo. Digite *menu* para ver as opções disponíveis para o seu perfil.`;
            }
        }

        // 3. Enviar a resposta via Evolution API
        if (replyText !== '') {
            await fetchApi(EVOLUTION_URL, {
                method: 'POST',
                headers: {
                    'apikey': EVOLUTION_API_KEY,
                    'Content-Type': 'application/json'
                },
                data: {
                    number: phone,
                    textMessage: {
                        text: replyText
                    }
                }
            });
        }

        results.push({ json: { phone, user: user.nome, command_detected: tl, response_sent: true } });

    } catch (error) {
        console.error('Workflow error:', error);
        results.push({ json: { error: error.message } });
    }
}

return results;
